    if scale in ('city', 'capital') and meta.get('walled'):
        maxgap = max([angs[i + 1] - angs[i] for i in range(len(angs) - 1)] + [angs[0] + 2 * math.pi - angs[-1]]) if angs else 2 * math.pi
    return _kept(locals(), ('i', 'maxgap'))


